function eligible(s){if(specialEvents().some(e=>e.speciesId===s.id))return true;if(['mewtwo','jigglypuff'].includes(s.id))return S.state.wins>0;const gym=gyms.find(g=>g.spirit===s.id);if(gym&&!S.state.gyms[gym.id]?.cleared)return false;if(s.id==='raichu'&&!(S.state.worldFlags.raichuSpawnUnlocked||S.state.items.thunderStone))return false;if(s.previous&&!owned(s.previous))return false;if(s.role==='legendary'||s.rarity==='傳說'){const list=spirits.filter(x=>x.role==='legendary'||x.rarity==='傳說'),index=list.indexOf(s),threshold=index<4?.25:index<8?.5:.75;return spirits.filter(x=>owned(x.id)).length/spirits.length>=threshold;}return true;}
