function captureBurst(position,color,success){const group=new T.Group(),ring=new T.Mesh(new T.RingGeometry(.48,.56,48),new T.MeshBasicMaterial({color,side:T.DoubleSide,transparent:true,opacity:1,depthWrite:false}));ring.rotation.x=-Math.PI/2;group.position.copy(position);group.add(ring);const stars=[];for(let i=0;i<(success?20:10);i++){const star=new T.Mesh(new T.OctahedronGeometry(success?.105:.065),new T.MeshBasicMaterial({color,transparent:true,opacity:1,depthWrite:false}));star.userData.direction=new T.Vector3(Math.cos(i*2.4),.2+Math.sin(i*1.7)*.6,Math.sin(i*2.4));group.add(star);stars.push(star);}scene.add(group);effects.push({object:group,start:elapsed,duration:success?1.25:.6,update:t=>{ring.scale.setScalar(.5+t*(success?5:2));ring.material.opacity=1-t;stars.forEach((s,i)=>{s.position.copy(s.userData.direction).multiplyScalar(t*(success?2.3:1.1));s.rotation.set(t*8,i+t*6,t*4);s.material.opacity=Math.sin(Math.PI*t);});},done:()=>disposeCaptureFx(group)});}
function sizeRule(species){const rule=modelSizeOverrides[species.id]||modelSizeOverrides[species.model]||{};return typeof rule==='number'?{desiredWorldHeight:rule}:rule;}
function updateFlight(a,dt){if(!a.airborne)return;a.flightRemaining-=dt;if(a.flightRemaining<=0){a.flightState=a.flightState==='air'?'ground':'air';a.flightRemaining=a.flightState==='air'?20+Math.random()*20:6+Math.random()*6;if(a.flightState==='air')a.flightAltitude=1.8+Math.random()*1.2;}a.flightBase=a.flightState==='air'?a.flightAltitude:0;const targetHeight=a.flightBase+(a.flightBase?Math.sin(elapsed*2.1+a.flightPhase)*.10:0);a.root.position.y+=(targetHeight-a.root.position.y)*(1-Math.exp(-3.8*dt));if(!a.flightBase&&a.root.position.y<.025)a.root.position.y=0;}
function collectPickup(a){const k=a.pickupKey,amount=k==='core'?5:k==='berry'?3:1;if(k==='core')S.state.pokeballs+=amount;else if(k==='great_core')S.state.greatBallCount+=amount;else if(k==='berry')S.state.berryCount+=amount;else{const item=k==='evolutionStone'?'thunderStone':'potion';S.state.items[item]=number(S.state.items[item])+amount;if(item==='thunderStone')S.state.worldFlags.raichuSpawnUnlocked=true;}a.root.visible=false;a.respawn=elapsed+90;a.root.position.copy(randomPoint());return({core:'靈核球',great_core:'高階靈核球',berry:'星露果',potion:'初光藥劑',evolutionStone:'雷光結晶'})[k]+' +'+amount;}
function showWorldBroadcast(text){const el=$('broadcast');if(el){clearTimeout(el.dismissTimer);el.textContent=text;el.hidden=false;layoutWorldNotifications();el.dismissTimer=setTimeout(()=>{el.hidden=true;layoutWorldNotifications();},12000);}}
function tickGuideBroadcast(){if(elapsed<guideBroadcastAt||place||battle||dialog||modal)return;const names={electric:'閃角兔電系套裝',mist:'星霧雲靈同行',sound:'絨心團獸音波套裝',healing:'暖巢福鹿治癒套裝'},tips=['圖鑑收錄達 25%、50%、75% 時，傳說幻靈會分批開放。持續締約不同種類，探索更多夥伴。','挑戰四座道館可依序取得 '+gyms.map(g=>names[g.costume]).join('、')+'，在旅人手冊的冒險衣櫃換裝。','雷光結晶可透過居民委託與場上補給取得；取得後能解鎖 '+(byId.raichu?.name||'雷系進階幻靈')+' 的出現條件。','同種幻靈重複締約滿三次，可在圖鑑消耗兩份羈絆進階；收錄進階前的夥伴，也會開放下一階段出現。','在 3 對 3 競技擂台取得勝利，會開放 '+[byId.mewtwo?.name,byId.jigglypuff?.name].filter(Boolean).join('、')+' 的出現條件。','找大夢博士領取冒險服；穿著後每 15 秒吸收城鎮中目前可見的補給，已收取的補給需等待 90 秒再生。'];const text='旅人攻略｜'+tips[guideBroadcastIndex++%tips.length];guideBroadcastAt=elapsed+300;showWorldBroadcast(text);}
async function spawnWild(species,position){const rule=sizeRule(species),height=Number(rule.desiredWorldHeight||rule.height)||1.275*Math.pow(1.3,Math.min(2,(species.stage||1)-1)),a=await actor(species.model,height);const bounds=posedBounds(a.object),dimensions=bounds.getSize(new T.Vector3()),maxSpan=Math.min(6,Number(rule.maxSpan)||6),ratio=Math.min(1,maxSpan/Math.max(dimensions.x,dimensions.z,.001));if(ratio<1){a.object.scale.multiplyScalar(ratio);a.object.position.multiplyScalar(ratio);a.height*=ratio;}a.species=species;a.root.position.copy(position||randomPoint());a.airborne=isAirborne(species);a.flightState=a.airborne?'air':'ground';a.flightAltitude=1.8+Math.random()*1.2;a.flightRemaining=20+Math.random()*20;a.flightBase=a.airborne?a.flightAltitude:0;a.flightPhase=Math.random()*Math.PI*2;a.root.position.y=a.flightBase;a.home=a.root.position.clone();a.goal=a.home.clone();a.timer=Math.random()*3;a.berry=false;wild.push(a);return a;}
async function populate(){await ensureSpecialAppearances();while(wild.length+spawnPending<WILD_LIMIT){const s=chooseWild();if(!s)break;await spawnWild(s);}}
async function replenish(){if(!S.ready)return;await ensureSpecialAppearances();if(wild.length+spawnPending>=WILD_LIMIT)return;spawnPending++;try{const s=chooseWild();if(s)await spawnWild(s);}catch(e){S.errors.push(e.message);}finally{spawnPending--;}}
async function spawnSupplies(){const keys=['core','great_core','berry','potion','evolutionStone'],colors={core:0xe3ac18,great_core:0x13d8e0,berry:0xf04eab,potion:0x51e478,evolutionStone:0xc27cff};await Promise.all(keys.map(async(key,i)=>{if(!world.props?.[key])return;const a=await actor(world.props[key],.55),clones=new Map();a.object.traverse(n=>{if(!n.isMesh)return;const list=(Array.isArray(n.material)?n.material:[n.material]).map(original=>{if(!clones.has(original)){const m=original.clone();const hsl={};m.color?.getHSL(hsl);if(m.color)m.color.setHSL(hsl.h,Math.max(.7,hsl.s),Math.max(.3,Math.min(.72,hsl.l)));m.emissive?.setHex(colors[key]);m.emissiveIntensity=.4;if(m.roughness!==undefined)m.roughness=.28;clones.set(original,m);}return clones.get(original)});n.material=Array.isArray(n.material)?list:list[0];});const halo=new T.Mesh(new T.RingGeometry(.31,.43,32),new T.MeshBasicMaterial({color:colors[key],transparent:true,opacity:.62,side:T.DoubleSide,depthWrite:false}));halo.rotation.x=-Math.PI/2;halo.position.y=-.22;a.root.add(halo);a.pickupHalo=halo;a.pickupKey=key;a.root.position.copy(randomPoint());a.root.position.y=.35;a.home=a.root.position.clone();a.respawn=0;pickups.push(a);}));}
function collectSupplies(){if(pickupCostume!==S.state.costume){pickupCostume=S.state.costume;adventureCollectAt=elapsed+15;}if(place||battle||modal||dialog)return;const automatic=S.state.costume==='adventure'&&elapsed>=adventureCollectAt,received=[];if(automatic)adventureCollectAt=elapsed+15;for(const a of pickups){if(a.respawn>elapsed){a.root.visible=false;continue;}a.root.visible=true;a.root.position.y=.4+Math.sin(elapsed*2)*.12;a.root.rotation.y+=.015;if(a.pickupHalo)a.pickupHalo.material.opacity=.45+Math.sin(elapsed*3)*.16;if(automatic||a.root.position.distanceTo(S.player)<1.3)received.push(collectPickup(a));}if(received.length){save();toast((automatic?'冒險服吸收補給｜':'取得補給｜')+received.join('、'));}}
function setCostume(id){S.state.costume=id;hero.object.traverse(n=>{if(n.userData.costume)n.visible=n.userData.costume===id||n.userData.costume==='trainer';});if(companion)companion.root.visible=id==='mist'&&!battle;save();}
async function loadNpc(n){const a=await actor(n.model,n.height||2.3,townGroup);a.data=n;a.root.position.fromArray(n.position||[0,0,0]);a.home=a.root.position.clone();a.goal=a.home.clone();a.timer=Math.random()*3;a.cooldown=0;addLabel(a,n.name+' · NPC');npcs.push(a);return a;}
function setNpcPlace(){for(const n of npcs){const match=place?n.data.buildingId===place.id:true;n.root.visible=match;(place?insideGroup:townGroup).add(n.root);if(match){const p=place?(n.data.interiorPosition||n.data.position):n.data.position;n.root.position.fromArray(p.length===2?[p[0],0,p[1]]:p);n.home.copy(n.root.position);n.goal.copy(n.home);}}}
async function enterBuilding(b){if(battle)return;cancelNavigation();clearTarget();closeDialog();$('loadText').textContent='走進'+b.name+'…';$('load').hidden=false;try{if(interior)insideGroup.remove(interior);const g=await asset(b.interiorModel);interior=g.scene.clone(true);insideGroup.add(interior);interior.traverse(n=>{if(n.isMesh){n.receiveShadow=true;n.castShadow=true;}});place=b;townGroup.visible=false;insideGroup.visible=true;detach(hero.root);insideGroup.add(hero.root);const p=b.spawn||[0,4];S.player.set(p[0],0,p.length===3?p[2]:p[1]);hero.root.position.copy(S.player);setNpcPlace();$('location').textContent=b.name;scene.fog.near=30;scene.fog.far=85;target=null;save();}catch(e){toast(e.message);S.errors.push(e.message);}finally{$('load').hidden=true;}}
function leaveBuilding(){if(!place)return;const p=place.entrance;S.player.set(p[0],0,p.length===3?p[2]:p[1]+2);place=null;insideGroup.visible=false;townGroup.visible=true;townGroup.add(hero.root);hero.root.position.copy(S.player);setNpcPlace();$('location').textContent='初光鎮';closeDialog();save();}
function portalCheck(){portalAction=null;if(battle||dialog||modal){$('portal').hidden=true;return;}if(place){const e=place.exit||[0,5];if(Math.hypot(S.player.x-e[0],S.player.z-(e.length===3?e[2]:e[1]))<2.1){portalAction=leaveBuilding;$('portal').textContent='離開'+place.name+' ↗';}}else for(const b of world.buildings){const p=b.entrance;if(Math.hypot(S.player.x-p[0],S.player.z-(p.length===3?p[2]:p[1]))<2.8){portalAction=()=>enterBuilding(b);$('portal').textContent='進入'+b.name+' ↗';break;}}$('portal').hidden=!portalAction;}
function openModal(title,html){closeDialog();stopViewer();modal=true;S.stick.x=S.stick.y=0;$('stick').style.transform='';$('modalTitle').textContent=title;$('modalBody').innerHTML=html;$('modal').hidden=false;}
function closeModal(){stopViewer();modal=false;$('modal').hidden=true;}
function closeDialog(){if(dialog){dialog.cooldown=elapsed+5;dialog.contactLock=true;}dialog=null;$('dialogue').hidden=true;}
function talk(n){if(modal||battle||dialog)return;cancelNavigation();dialog=n;S.stick.x=S.stick.y=0;$('stick').style.transform='';n.play('Idle');$('npcName').textContent=n.data.name;const lines=n.data.dialogue||['歡迎來到初光鎮！'];$('npcText').textContent=lines.map(line=>typeof line==='string'?line:line?.text||'').filter(Boolean).join('\n\n')||'祝你的旅途充滿新發現。';$('portrait').src=n.data.portraits?.normal||n.data.portrait||'';$('portrait').alt=n.data.name+'半身立繪';$('dialogue').hidden=false;const funcs=n.data.functions||[];let buttons='';if(n.data.id==='shop_vendor')buttons+='<button data-npc="pets">卡片兌換寵物</button>';if(funcs.some(f=>/heal|care|restore|回復/.test(f)))buttons+='<button data-npc="heal">休息與補給</button>';if(funcs.some(f=>/team|隊伍/.test(f)))buttons+='<button data-npc="team">整理隊伍</button>';if(funcs.some(f=>/quest|patrol|task|任務/.test(f)))buttons+='<button data-npc="quest">接受委託</button>';if(n.data.id==='prof_daydream'&&!S.state.adventureClaimed)buttons+='<button data-npc="adventure">領取冒險服</button>';else if(n.data.id!=='prof_daydream'&&funcs.some(f=>/research|dex|starter|研究/.test(f)))buttons+='<button data-npc="research">生態研究</button>';if(funcs.some(f=>/battle|arena|challenge|gym|對戰/.test(f))&&!funcs.some(f=>/tower/.test(f)))buttons+='<button data-npc="battle">3 對 3 對戰</button>';if(funcs.some(f=>/tower/.test(f))||n.data.buildingId==='tower_starspire')buttons+='<button data-npc="tower">開始星穹挑戰</button>';if(n.data.buildingId==='gym_light')buttons+='<button data-npc="gym">道館挑戰</button>';buttons+='<button data-npc="gift">問候與補給</button><button data-npc="close">離開</button>';$('npcActions').innerHTML=buttons;if(n.data.id==='prof_daydream'&&S.state.adventureClaimed)$('npcText').textContent+='\n\n已領得冒險服：穿著後每 15 秒自動吸收附近可見補給。';const gift=maybeNpcGift(n);if(gift)$('npcText').textContent+=' '+gift;}
function npcAction(action){const n=dialog;if(!n)return;const s=S.state;if(action==='close')return closeDialog();if(action==='pets'){closeDialog();return showPetShop();}if(action==='adventure'&&n.data.id==='prof_daydream'){if(!s.adventureClaimed){s.adventureClaimed=true;if(!s.unlockedCostumes.includes('adventure'))s.unlockedCostumes.push('adventure');$('npcText').textContent='已領得冒險服！在旅人手冊 → 冒險衣櫃穿上後，每 15 秒自動收集附近可見補給，不必逐一走近。';$('npcActions').querySelector('[data-npc="adventure"]')?.remove();toast('已領得冒險服｜每 15 秒自動吸收附近補給');save();}return;}if(action==='team'){closeDialog();return showTeam();}if(action==='battle'){closeDialog();return startBattle('arena');}if(action==='gym'){closeDialog();return showGyms();}if(action==='tower'){save();location.href='tower/';return;}if(action==='heal'){const key=n.data.id+'-care',last=number(s.npcRewards[key]);if(Date.now()-last>=120000){s.npcRewards[key]=Date.now();s.items.potion=number(s.items.potion)+2;s.pokeballs=Math.max(s.pokeballs,15);$('npcText').textContent='夥伴已恢復精神！靈核球補足至 15 顆，並領取 2 份初光藥劑。';}else $('npcText').textContent='夥伴已恢復精神！補給每兩分鐘準備一次，請稍後再來。';}if(action==='quest'){const count=spirits.filter(x=>owned(x.id)).length;if(count>=5&&!s.quests.firstResearch){s.quests.firstResearch=true;s.items.thunderStone=number(s.items.thunderStone)+1;s.worldFlags.raichuSpawnUnlocked=true;$('npcText').textContent='你已締約 5 種幻靈，巡護委託完成！獲得雷光結晶；新的進階幻靈已能在城鎮出現。';}else $('npcText').textContent=s.quests.firstResearch?'初光鎮的安全，就交給我們一起守護。':'委託：締約 5 種不同幻靈，再回來領取雷光結晶。';}if(action==='research'){$('npcText').textContent='御靈的第一步是觀察。重複締約可累積進階所需的羈絆；在圖鑑中選擇夥伴，查看進階鏈。';}if(action==='gift'){$('npcText').textContent=maybeNpcGift(n,true)||'補給還在準備中，過一會兒再來找我吧。';}if(n.data.portraits?.happy)$('portrait').src=n.data.portraits.happy;save();}
function showMenu(){openModal('旅人手冊',`<div class="menuGrid"><button data-menu="dex">✦ 幻靈圖鑑</button><button data-menu="team">☷ 幻靈隊伍</button><button data-menu="monsters">◇ 魔物圖鑑</button><button data-menu="bgm">♫ 背景音樂</button><button data-menu="costume">◇ 冒險衣櫃</button><button data-menu="gym">⚑ 初光挑戰</button><button data-menu="tower">✧ 星穹挑戰塔</button><button data-menu="pets">♧ 寵物商人</button><button data-menu="bag">◈ 旅人背包</button><button data-menu="guide">⌖ 建物與居民</button><button data-menu="help">？旅行指南</button><button data-menu="studio">↗ Blender 模型室</button><button data-menu="reset" class="danger">重置遊戲</button></div><p class="muted">進度自動保存在此瀏覽器，重新整理或回到同一網址可繼續遊玩。清除網站資料或更換裝置不會保留紀錄。</p>`);}
function showPetShop(){
 const t=towerProgress();
 const rows=TOWER_PETS.map(p=>{const count=number(t.cards[p.card]),owned=!!t.pets[p.id],active=S.state.petActive===p.id;
 return '<div class="row"><span><strong>'+p.name+'</strong><small style="display:block">需要 '+p.card+' ×'+p.cost+' ｜目前 '+count+' 張</small></span><button data-pet="'+p.id+'" '+(!owned&&count<p.cost?'disabled':'')+'>'+(active?'取消隨行':owned?'設為隨行':'兌換寵物')+'</button></div>';}).join('');
 openModal('寵物商人・卡片兌換','<p class="muted">挑戰塔掉落的卡片可換取永久寵物。兌換後可選擇一隻在初光鎮隨行。已登錄的圖鑑紀錄不會因兌換而消失。</p>'+rows);
}
async function equipPet(id){
 if(petFollower){removeActor(petFollower);petFollower=null;}
 const p=TOWER_PETS.find(x=>x.id===id);if(!p||!byId[p.model]||!S.state.petActive)return;
 try{petFollower=await actor(byId[p.model].model,.88);petFollower.root.visible=!place&&!battle;petFollower.play('Walk');}catch(err){console.warn('寵物載入失敗',err);toast('寵物模型載入失敗，請重新進入遊戲。');}
}
function changePet(id){
 const p=TOWER_PETS.find(x=>x.id===id);if(!p)return;const t=towerProgress(),count=number(t.cards[p.card]);
 if(!t.pets[p.id]){if(count<p.cost)return toast('卡片不足，請先挑戰魔物。');t.cards[p.card]=count-p.cost;t.pets[p.id]=true;if(!saveTowerProgress(t))return toast('無法儲存寵物兌換，請檢查網站儲存權限。');}
 S.state.petActive=S.state.petActive===p.id?null:p.id;save();equipPet(S.state.petActive);showPetShop();
}
function towerCardCounts(){const t=towerProgress();return Object.fromEntries(towerMonsters.map(s=>[s.id,number(t.cards[s.name+'卡片'])]));}
function towerCardOwned(id){const t=towerProgress(),s=towerMonsters.find(s=>s.id===id);return !!s&&(!!t.registeredCards?.[s.name+'卡片']||number(t.cards[s.name+'卡片'])>0);}
function monsterCard(s,detail=false){const n=number(towerCardCounts()[s.id]),registered=towerCardOwned(s.id),color=s.id==='fire'?'red':'purple',moves={forest:[['衝鋒突進',32],['古林震地',34]],ice:[['霜牙衝刺',32],['冰圈爆破',29]],fire:[['烈焰吐息',38],['熔岩爆發',29]]}[s.id]||[];const card=`<article class="collectionCard towerMonsterCard" data-frame="${color}" data-locked="${!registered}"><img class="collectionArt" src="${esc(s.portrait)}" alt="${esc(s.name)}肖像" loading="lazy" decoding="async"><img class="collectionFrame" src="assets/cards/frame.png" alt="" decoding="async"><h3 class="collectionName">${registered?esc(s.name):'未知魔物'}</h3><div class="collectionInfo"><div class="collectionType">${registered?esc(s.element):'???'} · 挑戰塔魔物</div><div class="collectionStats"><span>HP ${registered?s.hp:'???'}</span><span>攻擊 ${registered?s.attack:'???'}</span><span class="collectionBond">卡牌 ×${n}</span></div><ul class="collectionSkills">${moves.map(([name,power])=>`<li><span>${name}</span><b>${power}／傷害</b></li>`).join('')}</ul><div class="collectionSynopsis">${esc(s.description.slice(0,28))}…</div></div></article>`;return detail?card:`<button class="collectionThumb towerMonsterThumb" data-monster="${s.id}" ${registered?'':'disabled'} aria-label="${registered?'查看'+esc(s.name)+'卡牌':'未取得魔物卡牌，擊敗後解鎖'}">${card}</button>`;}
function showMonsterDex(){openModal('挑戰塔魔物圖鑑',`<div class="toolbar"><button data-menu="dex">← 幻靈圖鑑</button><button data-menu="tower">前往挑戰塔</button></div><p class="muted">三種魔物以挑戰塔戰鬥取得收藏卡。擊敗後有 4% 機率掉落卡牌，靠近卡牌手動拾取後收錄，素材與卡片會自動儲存。</p><div class="towerMonsterGrid">${towerMonsters.map(s=>monsterCard(s)).join('')||'<p>魔物卡牌尚未載入，請重新整理。</p>'}</div>`);}
function showMonsterDetail(id){const s=towerMonsters.find(s=>s.id===id);if(!s)return;if(!towerCardOwned(id))return toast('擊敗這隻魔物後才會取得收藏卡。');openModal(s.name+' · 魔物收藏卡',`<div class="collectionDetail towerMonsterDetail">${monsterCard(s,true)}<p class="collectionDescription">${esc(s.description)}</p><p class="collectionEvolution">${towerCardOwned(s.id)?'已登錄圖鑑':'拾取魔物卡牌後收錄'} · 攻擊欄為憤怒狀態最高傷害</p></div><div class="toolbar"><button data-menu="monsters">返回魔物圖鑑</button><button data-menu="tower">前往挑戰塔</button></div>`);}
function towerDexHtml(){return `<section class="towerDex"><h3>星穹挑戰塔 · 魔物卡牌</h3><div class="towerMonsterGrid">${towerMonsters.map(s=>monsterCard(s)).join('')}</div></section>`;}
function showBag(){openModal('旅人背包',`<div class="row">靈核球 <b>${S.state.pokeballs}</b></div><div class="row">高階靈核球 <b>${S.state.greatBallCount}</b></div><div class="row">星耀靈核球 <b>${S.state.masterBallCount}</b></div><div class="row">星露果 <b>${S.state.berryCount}</b></div>${Object.entries(itemNames).map(([k,n])=>`<div class="row">${n}<b>${number(S.state.items[k])}</b></div>`).join('')}<p class="muted">回復藥恢復生命；裂甲粉降低敵方防禦；勇氣結晶提升我方攻擊。可從居民對話及不定時補給廣播獲得。</p>`);}
function exportSave(){showReset();}
function showHelp(){openModal('旅行指南','<p>左側搖桿移動，右側「鎖定」自動選取可締約幻靈，再按「締約」投出靈核球。星露果可提高成功率；換球切換普通、高階與星耀球。</p><p>桌面 WASD／方向鍵移動，空白締約、E 進出、Tab 鎖定／解除目標、Shift 翻滾。翻滾沒有冷卻，完成動作後可再次翻滾。拖曳場景旋轉，雙指捏合或滾輪縮放；小型鏡頭按鈕也可操作。</p><p>手冊「建物與居民」點名稱即可自動導航。操作方向鍵或按取消可中止導航。碰到居民就會對話，有機會得到回復、減防、加攻道具及締約用品。</p><p>場上維持 8 隻幻靈；已捕捉越多的種類出現率越低。重複締約三次，可在圖鑑消耗兩份羈絆進階。</p><p>初光挑戰：旅人在特色道館移動、翻滾閃避推離與短暫干擾，投靈核球累積信任完成試煉，旅人不會受傷。通關後守護神獸會出現於初光鎮，每三分鐘公告，捕獲該隻後公告停止。競技擂台則是幻靈小隊回合對戰，技能可附加狀態，使用道具或換位應對。</p><p>進度自動存於此瀏覽器。手冊的重置需兩次確認。星穹挑戰塔已開放三層魔物挑戰，靠近武器範圍會自動攻擊，原攻擊鍵改為換武器。</p>');}
const artCache=new Map(),artQueue=[];let artBusy=false;
const decodedCardImages=new Map();
function decodeCardImage(src){if(!src)return Promise.resolve(null);if(decodedCardImages.has(src)){const cached=decodedCardImages.get(src);decodedCardImages.delete(src);decodedCardImages.set(src,cached);return cached.promise;}const image=new Image();image.decoding='async';image.src=src;const entry={image,ready:false,promise:null};entry.promise=(image.decode?image.decode():new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=reject})).then(()=>{entry.ready=true;return image}).catch(()=>null);decodedCardImages.set(src,entry);while(decodedCardImages.size>8){const oldest=Array.from(decodedCardImages.keys()).find(key=>key!=='assets/cards/frame.png');if(!oldest)break;decodedCardImages.delete(oldest);}return entry.promise;}
function cardArtSource(s){const entry=cardArt[s.id];return entry?(typeof entry==='string'?entry:entry.path||entry.image||entry.src):artCache.get(s.id);}
function warmCollectionArt(s){if(!s)return;decodeCardImage('assets/cards/frame.png');const src=cardArtSource(s);if(src)decodeCardImage(src);}
setInterval(()=>{if(!S.ready||modal||battle||document.hidden)return;const current=target?.species||wild.filter(w=>w.root.visible).sort((a,b)=>a.root.position.distanceToSquared(S.player)-b.root.position.distanceToSquared(S.player))[0]?.species;warmCollectionArt(current);},1200);
function requestArt(s,img){if(!s||!img)return;img.decoding='async';img.alt=s.name+' · 2D 動感插畫';const src=cardArtSource(s);if(src){if(img.closest('.collectionThumb')){img.loading='lazy';img.src=src;return;}const start=performance.now(),cached=decodedCardImages.get(src);img.dataset.predecoded=String(!!cached?.ready);const show=image=>{if(!img.isConnected)return;img.src=src;img.dataset.decodeMs=(performance.now()-start).toFixed(1);if(image)img.dataset.decodedSize=image.naturalWidth+'×'+image.naturalHeight;const card=img.closest('.collectionCard');if(card)card.dataset.artReadyMs=(performance.now()-Number(card.dataset.openStarted||start)).toFixed(1);};if(cached?.ready)show(cached.image);else decodeCardImage(src).then(show);return;}artQueue.push({s,img});processArt();}
async function processArt(){if(artBusy)return;artBusy=true;while(artQueue.length){const {s,img}=artQueue.shift();if(!img.isConnected)continue;try{if(!artCache.has(s.id))artCache.set(s.id,await snapshot(s));if(img.isConnected)img.src=artCache.get(s.id);}catch(e){S.errors.push(e.message);img.alt=s.name+'模型圖載入失敗';}}artBusy=false;}
let artRenderer;
async function snapshot(s){const g=await asset(s.model);if(!artRenderer){artRenderer=new T.WebGLRenderer({antialias:true,alpha:true,preserveDrawingBuffer:true});artRenderer.setSize(320,320);artRenderer.outputEncoding=T.sRGBEncoding;artRenderer.toneMapping=T.ACESFilmicToneMapping;artRenderer.toneMappingExposure=1.05;}const st=new T.Scene();st.add(new T.HemisphereLight(0xe0f4ff,0xabaa87,1));const key=new T.DirectionalLight(0xffedda,1.5);key.position.set(-3,5,4);st.add(key);const o=cloneSkin(g.scene);st.add(o);o.rotation.y=.35;o.updateMatrixWorld(true);const b=posedBounds(o),size=b.getSize(new T.Vector3()),center=b.getCenter(new T.Vector3());const c=new T.PerspectiveCamera(33,1,.01,100),r=Math.max(size.y,size.x,size.z)*1.9;c.position.set(center.x+r*.28,center.y+r*.18,center.z+r);c.lookAt(center);artRenderer.render(st,c);return artRenderer.domElement.toDataURL('image/png');}
function showDex(){openModal('幻靈圖鑑',`<div class="toolbar"><input id="dexSearch" placeholder="搜尋已締約幻靈" aria-label="搜尋幻靈"><select id="dexFilter"><option value="all">全部 ${spirits.length} 種</option><option value="owned">已締約</option><option value="1">第一階段</option><option value="2">第二階段</option><option value="3">第三階段</option></select></div><div class="cards" id="cardGrid"></div>${towerDexHtml()}`);renderCards();$('dexSearch').oninput=renderCards;$('dexFilter').onchange=renderCards;}
const heroOutcomeNames=['Celebrate','JumpCelebrate','Disappointed','GroundPoundDisappointed'],townGrassMeshes=[];let townGrassMetadata=null;
function prepareHeroOutcomeActions(){if(!hero)return;for(const name of heroOutcomeNames)if(hero.actions[name])hero.actions[name].setEffectiveTimeScale(2.5);}
function playHeroOutcome(success){prepareHeroOutcomeActions();const candidates=(success?['Celebrate','JumpCelebrate']:['Disappointed','GroundPoundDisappointed']).filter(name=>hero.actions[name]),name=candidates[Math.random()<.5?0:candidates.length-1]||'Idle';hero.play(name,true);const action=hero.actions[name];return {name,duration:action?Math.max(.05,action.getClip().duration/(heroOutcomeNames.includes(name)?2.5:1)):.1};}
async function loadTownGrass(){const r=await fetch('data/grass-patches.json?v=20261014-snail-release');if(!r.ok)throw Error('短草配置未就緒');const data=await r.json(),g=await asset(data.model),source=g.scene;source.updateMatrixWorld(true);const bounds=new T.Box3().setFromObject(source),baseHeight=Math.max(.001,bounds.max.y-bounds.min.y),patches=data.patches||[],range=data.heightRange||[.08,.22];townGrassMetadata=data;source.traverse(node=>{if(!node.isMesh)return;const materials=Array.isArray(node.material)?node.material.map(m=>m.clone()):node.material.clone(),mesh=new T.InstancedMesh(node.geometry,materials,patches.length);mesh.name='短草・可穿越';mesh.userData.townGrass=true;mesh.userData.collision=false;mesh.frustumCulled=false;mesh.receiveShadow=true;mesh.castShadow=false;for(let i=0;i<patches.length;i++){const patch=patches[i],pos=patch.position||[0,0,0],scale=patch.scale||[1,1,1],height=range[0]+(range[1]-range[0])*(((i*73+19)%101)/100),matrix=new T.Matrix4().compose(new T.Vector3(pos[0],(pos[1]||0)+.005,pos[2]),new T.Quaternion().setFromAxisAngle(new T.Vector3(0,1,0),patch.yaw||0),new T.Vector3(scale[0],height/baseHeight,scale[2]));matrix.multiply(node.matrixWorld);mesh.setMatrixAt(i,matrix);}mesh.instanceMatrix.needsUpdate=true;townGroup.add(mesh);townGrassMeshes.push(mesh);});}
function collectionCardHtml(s){return `<article class="collectionCard" data-collection="${esc(s.id)}"><img class="collectionArt" data-art="${esc(s.id)}" decoding="async" alt="${esc(s.name)}的原創插畫"><img class="collectionFrame" src="assets/cards/frame.png" decoding="async" alt=""><h3 class="collectionName">${esc(s.name)}</h3><div class="collectionInfo"><div class="collectionType">${esc(s.type||s.element)} · ${esc(s.rarity||'普通')} · 第 ${s.stage||1} 階段</div><div class="collectionStats"><span>HP ${s.hp}</span><span>攻擊 ${s.attack}</span><span class="collectionBond">羈絆 ×${number(S.state.captureCounts[s.id])}</span></div><ul class="collectionSkills">${(s.skills||[]).slice(0,2).map(k=>`<li><span>${esc(k.name)}</span><b>${k.power}／${k.cost||1}能量</b></li>`).join('')}</ul><div class="collectionSynopsis">${esc((s.description||'初光鎮的原創幻靈夥伴。').slice(0,30))}${(s.description||'').length>30?'…':''}</div></div></article>`;}
async function collectDuplicateCard(s,worldPosition){const node=document.createElement('div');node.className='collectionPickup';node.dataset.spirit=s.id;node.innerHTML=collectionCardHtml(s);document.body.append(node);requestArt(s,node.querySelector('[data-art]'));const p=worldPosition.clone().project(camera),sx=(p.x*.5+.5)*innerWidth,sy=(-p.y*.5+.5)*innerHeight;node.style.left=(sx-35)+'px';node.style.top=(sy-49)+'px';try{await captureTween(.45,t=>{node.style.transform=`translateY(${-t*28}px) rotateY(${t*360}deg) scale(${.75+t*.25})`;});const r=$('dexBtn').getBoundingClientRect(),ex=r.x+r.width/2,ey=r.y+r.height/2,cx=sx+(ex-sx)*.35,cy=Math.max(20,Math.min(sy,ey)-120);await captureTween(.95,t=>{const u=1-t,x=u*u*sx+2*u*t*cx+t*t*ex,y=u*u*(sy-28)+2*u*t*cy+t*t*ey;node.style.left=(x-35)+'px';node.style.top=(y-49)+'px';node.style.transform=`rotate(${t*18}deg) scale(${1-t*.8})`;node.style.opacity=String(1-Math.max(0,t-.8)*5);});$('dexBtn').animate([{filter:'brightness(1)'},{filter:'brightness(2)',transform:'scale(1.12)'},{filter:'brightness(1)',transform:'scale(1)'}],{duration:500});}finally{node.remove();}}
function renderCards(){const q=$('dexSearch').value,filter=$('dexFilter').value,list=spirits.filter(s=>(!q||owned(s.id)&&s.name.includes(q))&&(filter==='all'||filter==='owned'&&owned(s.id)||String(s.stage)===filter));$('cardGrid').innerHTML=list.map(s=>owned(s.id)?`<button class="collectionThumb" data-detail="${s.id}" aria-label="查看${esc(s.name)}收藏卡">${collectionCardHtml(s)}</button>`:'<div class="card locked"><small>未締約</small><div class="seal">◇</div><strong>未知幻靈</strong><p class="muted">等待旅途中的相遇</p></div>').join('');$('cardGrid').querySelectorAll('.collectionFrame').forEach(img=>img.loading='lazy');$('cardGrid').querySelectorAll('[data-art]').forEach(img=>requestArt(byId[img.dataset.art],img));}
function showDetail(id){const s=byId[id];if(!s||!owned(id))return;const next=byId[s.evolvesTo||s.next],openStarted=performance.now();warmCollectionArt(s);openModal(s.name,`<div class="collectionDetail">${collectionCardHtml(s)}<div class="collectionDetailActions"><button data-view="${id}" class="primary">查看 3D 模型</button><button data-add="${id}">加入隊伍</button>${next?`<button data-evolve="${id}" ${number(S.state.captureCounts[id])<3?'disabled':''}>進階 · 3 份羈絆</button>`:''}</div><p class="collectionDescription">${esc(s.description||'初光鎮的原創幻靈夥伴。')}</p><p class="collectionEvolution">${esc(byId[s.previous]?.name||'起始')} → ${esc(s.name)}${next?' → '+esc(next.name):''}</p></div>`);const card=$('modalBody').querySelector('.collectionCard');card.dataset.openStarted=String(openStarted);card.dataset.structureMs=(performance.now()-openStarted).toFixed(1);requestArt(s,card.querySelector('[data-art]'));}
function evolve(id){const s=byId[id],next=byId[s.evolvesTo||s.next];if(!next||number(S.state.captureCounts[id])<3)return;S.state.captureCounts[id]-=2;grant(next.id);toast('羈絆綻放！'+next.name+'加入旅途。');showDetail(next.id);}
function showTeam(){openModal('幻靈隊伍 · 3 對 3',`<p class="muted">上場順序由上至下。最多三位夥伴；在圖鑑中加入已締約幻靈。</p>${S.state.team.map((id,i)=>`<div class="row"><span>${i+1}. ${esc(byId[id]?.name||id)}</span><button data-remove="${id}">移出</button></div>`).join('')||'<p>尚未加入夥伴，先去探索締約吧。</p>'}<div class="toolbar" style="margin-top:18px"><button data-menu="dex">前往圖鑑</button><button data-arena="arena" class="primary" ${S.state.team.length?'':'disabled'}>與擂台旅人切磋</button></div>`);}
function showCostumes(){const names={trainer:'初光旅人',adventure:'博士贈送冒險服',electric:'閃角兔電系套裝',mist:'星霧雲靈同行',sound:'絨心團獸音波套裝',healing:'暖巢福鹿治癒套裝'};openModal('冒險衣櫃',Object.entries(names).map(([id,name])=>`<div class="row"><span>${name}</span><button data-costume="${id}" ${S.state.unlockedCostumes.includes(id)?'':'disabled'}>${S.state.costume===id?'穿著中':S.state.unlockedCostumes.includes(id)?'換裝':id==='adventure'?'向大夢博士領取':'道館解鎖'}</button></div>`).join(''));}
const gyms=[{id:'gym_1',spirit:'pikachu',costume:'electric'},{id:'gym_2',spirit:'mew',costume:'mist'},{id:'gym_3',spirit:'wigglytuff',costume:'sound'},{id:'gym_4',spirit:'blissey',costume:'healing'}];
function showGyms(){openModal('初光挑戰 · 四大守護者',`<p class="muted">親自走進 3D 試煉場，移動與翻滾避開推離和短暫干擾，投擲靈核球累積守護者的信任。旅人不會受到傷害；完成試煉解鎖專屬變裝，守護神獸將出現於初光鎮等待正式締約。幻靈競技則保留獨立 3 對 3 對決。</p><div class="cards">${gyms.map((g,i)=>`<button class="card" data-arena="${g.id}"><small>試煉 ${i+1} · ${['雷電奔襲','星霧念動','絨心音浪','暖巢治癒'][i]}</small><img data-art="${g.spirit}" alt="${esc(byId[g.spirit]?.name)}"><strong>${esc(byId[g.spirit]?.name)}</strong><div class="stats">${S.state.gyms[g.id]?.cleared?'✓ 已完成':'進入試煉 · 解鎖專屬裝備'}</div></button>`).join('')}</div>`);$('modalBody').querySelectorAll('[data-art]').forEach(img=>requestArt(byId[img.dataset.art],img));}
async function showViewer(id){const s=byId[id];if(!s)return;openModal(s.name+' · 3D 模型','<div class="viewer" id="viewer"></div><p class="viewerNote">拖曳旋轉 · 滾輪縮放 · Blender 原創模型</p><div class="toolbar"><button data-vmotion="Idle">待機</button><button data-vmotion="Walk">行走</button><button data-vmotion="Attack">攻擊</button><button data-detail="'+id+'">返回收藏卡</button></div>');const host=$('viewer'),g=await asset(s.model);if(!host.isConnected)return;const r=new T.WebGLRenderer({antialias:true,alpha:false});r.setPixelRatio(Math.min(devicePixelRatio,1.7));r.setSize(host.clientWidth,host.clientHeight);r.outputEncoding=T.sRGBEncoding;r.toneMapping=T.ACESFilmicToneMapping;host.append(r.domElement);const st=new T.Scene();st.background=new T.Color('#192c42');st.add(new T.HemisphereLight(0xd8eeff,0x7c7183,1.3));const l=new T.DirectionalLight(0xffe6ca,2);l.position.set(-3,5,4);st.add(l);const o=cloneSkin(g.scene);st.add(o);const box=posedBounds(o),center=box.getCenter(new T.Vector3()),size=box.getSize(new T.Vector3()),cam=new T.PerspectiveCamera(36,host.clientWidth/host.clientHeight,.01,100),mix=new T.AnimationMixer(o),acts={};g.animations.forEach(c=>acts[c.name]=mix.clipAction(c));viewer={r,st,cam,o,mix,acts,center,distance:Math.max(size.x,size.y,size.z)*2,yaw:.3,pitch:.15};viewerMotion('Idle');let last=null;host.onpointerdown=e=>{last=[e.clientX,e.clientY];host.setPointerCapture(e.pointerId)};host.onpointermove=e=>{if(last&&viewer){viewer.yaw-=(e.clientX-last[0])*.012;viewer.pitch=Math.max(-.35,Math.min(.8,viewer.pitch+(e.clientY-last[1])*.009));last=[e.clientX,e.clientY];}};host.onpointerup=()=>last=null;host.onwheel=e=>{e.preventDefault();viewer.distance*=e.deltaY>0?1.1:.9;},{passive:false};}
function viewerMotion(n){if(!viewer)return;Object.values(viewer.acts).forEach(a=>a.stop());const name=Object.keys(viewer.acts).find(k=>k.toLowerCase().includes(n.toLowerCase()));if(name)viewer.acts[name].reset().play();}
function stopViewer(){if(viewer){viewer.mix.stopAllAction();viewer.r.dispose();viewer.r.domElement.remove();viewer=null;}}
function selectTarget(cycle=false){if(place||battle&&!battle.gym||throwing)return;const nearby=wild.filter(w=>w.root.visible&&w.root.parent===townGroup&&eligible(w.species)).sort((a,b)=>a.root.position.distanceTo(S.player)-b.root.position.distanceTo(S.player));if(!nearby.length){clearTarget();if(cycle)toast('目前沒有可締約的幻靈。');return;}if(!target||!nearby.includes(target))target=nearby[0];else if(cycle)target=nearby[(nearby.indexOf(target)+1)%nearby.length];if(cycle){locked=true;$('lockBtn').setAttribute('aria-pressed','true');$('lockBtn').setAttribute('aria-label','解除幻靈鎖定');$('lockBtn').title='解除鎖定';const dx=target.root.position.x-S.player.x,dz=target.root.position.z-S.player.z;hero.root.rotation.y=Math.atan2(dx,dz);cameraOrbit.yaw=Math.atan2(-dx,-dz);if(lockLabel)removeLabel(lockLabel);lockLabel=addLabel(target,'▼ '+target.species.name+' · 已鎖定','nameLabel targetLabel');showLockMarker(target);toast('已鎖定 '+target.species.name+(target.root.position.distanceTo(S.player)>12?'，請再靠近投擲。':''));}}
function useBerry(){if(!target)return toast('先靠近幻靈並鎖定牠。');if(S.state.berryCount<1)return toast('星露果不足，可以向居民詢問補給。');if(target.berry)return toast('牠已經吃過星露果了。');S.state.berryCount--;target.berry=true;save();toast(target.species.name+'放下戒心，下次締約更容易成功！');}
